def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    stripes=[]
    for r in range(h):
        nz=[c for c,v in enumerate(grid[r]) if v]
        if len(nz)>=3: stripes.append((r,min(nz),max(nz),grid[r][nz[0]]))
    markers=[]
    for c in range(w):
        if any(grid[r][c] for r in range(h) if r>max((s[0] for s in stripes),default=-1)):
            markers.append(c)
    for c in markers:
        prev=-1
        for r,left,right,color in stripes:
            if left<=c<=right:
                if grid[r][c]==0:
                    for rr in range(prev+1,r+1):
                        if out[rr][c]==0: out[rr][c]=color
                prev=r
    return out
